def solve(rows):
    # Filter rows as before
    filtered_rows = [row for row in rows if row["day"] <= 20]

    # Group by carrier
    carrier_groups = {}
    for row in filtered_rows:
        carrier = row["carrier"]
        if carrier not in carrier_groups:
            carrier_groups[carrier] = []
        carrier_groups[carrier].append(row)

    # Calculate median units for each carrier
    result = {}
    for carrier, group in carrier_groups.items():
        units = [row["units"] for row in group]
        n = len(units)
        if n % 2 == 1:
            median = sorted(units)[n // 2]
        else:
            median = (sorted(units)[n // 2 - 1] + sorted(units)[n // 2]) / 2
        result[carrier] = round(median, 1)

    # Prepare the output
    output = []
    for carrier, value in result.items():
        if value >= 20:
            output.append((carrier, value))

    # Sort by value descending, then by carrier alphabetically
    output.sort(key=lambda x: (-x[1], x[0]))

    # Return the result
    return output
