def solve(rows):
    balance = 0
    min_balance = 0
    earliest_day = None
    for row in sorted(rows, key=lambda x: (x['day'], x['visit_id'])):
        if row['outcome'] == 'no_show':
            balance += row['duration_min']
        elif row['outcome'] == 'completed':
            balance -= row['duration_min']
        else:
            continue
        if balance < min_balance:
            min_balance = balance
            earliest_day = row['day']
    return [min_balance, earliest_day] if earliest_day is not None else [0, None]
```

