def solve(rows):
    balance = 0
    min_balance = float('inf')
    min_day = None
    no_show_count = 0

    for row in rows:
        if row['outcome'] == 'no_show':
            no_show_count += 1
            duration = row['duration_min']
            balance += duration
        elif row['outcome'] == 'completed':
            duration = row['duration_min']
            balance -= duration
        # Ignore other rows

        # Update min balance and day if we have a non-ignored row
        if balance != 0:
            if balance < min_balance:
                min_balance = balance
                min_day = row['day']
            elif balance == min_balance:
                if row['day'] < min_day:
                    min_day = row['day']

    if no_show_count == 0:
        return [0, None]
    else:
        return [min_balance, min_day]
```

