        completed = data['completed']
        total = data['total']
        percentage = round(100 * completed / total, 1)
        if percentage >= 30:
            result.append([department, percentage])

    # Sort by percentage (descending), then by department name (ascending)
    result.sort(key=lambda x: (-x[1], x[0]))

    return result
