    doctor_medians = {}
    for doctor, durations in doctor_durations.items():
        sorted_durations = sorted(durations)
        n = len(sorted_durations)
        mid = n // 2
        if n % 2 == 1:
            median = sorted_durations[mid]
        else:
            median = (sorted_durations[mid - 1] + sorted_durations[mid]) / 2
        doctor_medians[doctor] = round(median, 1)

    return doctor_medians
