def solve(rows):
    # Filter rows where day is 18 or less
    filtered_rows = [row for row in rows if row["day"] <= 18]

    # If no rows, return None
    if not filtered_rows:
        return None

    # Group rows by department and calculate the sum of duration_min * fee
    department_sums = {}
    for row in filtered_rows:
        department = row["department"]
        duration = row["duration_min"]
        fee = row["fee"]
        key = (department, fee, duration)
        if key not in department_sums:
            department_sums[key] = 0
        department_sums[key] += duration * fee

    # Extract unique departments and their total sum
    department_totals = {}
    for department, fee, duration in department_sums:
        if department not in department_totals:
            department_totals[department] = 0
        department_totals[department] += duration * fee

    # Find the department with the highest total, breaking ties by alphabetical order
    max_total = -1
    best_department = None
    for department in sorted(department_totals.keys()):
        total = department_totals[department]
        if total > max_total:
            max_total = total
            best_department = department

    return best_department
```

