        if balance < min_balance:
            min_balance = balance
            min_day = row["day"]
        elif balance == min_balance:
            # Check if the day is earlier
            if row["day"] < min_day:
                min_day = row["day"]

    # Return the result
    if min_balance != 0:
        return [min_balance, min_day]
    else:
        return [0, None]
