    max_length = 0
    start_day = None
    current_length = 0
    current_start = None

    for day in days:
        if current_start is None:
            current_start = day
            current_length = 1
        else:
            if day == current_start + current_length:
                current_length += 1
            else:
                if current_length > max_length:
                    max_length = current_length
                    start_day = current_start
                current_start = day
                current_length = 1

    if current_length > max_length:
