def solve(rows):
    # Initialize variables
    balance = 0
    min_balance = float('inf')
    min_day = None

    # Process rows in ascending order (day, trip_id)
    for row in sorted(rows, key=lambda x: (x["day"], x["trip_id"])):
        result = row["result"]

        if result == "on_time":
            balance += row["packages"]
        elif result == "aborted":
            balance -= row["packages"]

        # Check if the balance is updated
        if balance != 0:
            if balance < min_balance:
                min_balance = balance
                min_day = row["day"]
            elif balance == min_balance:
                # Prefer the earliest day
                if row["day"] < min_day:
                    min_day = row["day"]

    # Return the result based on the minimum balance
    if min_balance == float('inf'):
        return [0, None]
    else:
        return [min_balance, min_day]
