def solve(rows):
    filtered_rows = [row for row in rows if row['day'] <= 24]
    days = sorted(set(row['day'] for row in filtered_rows))
    if not days:
        return [0, None]
    max_length = 1
    current_length = 1
    start_day = days[0]
    for i in range(1, len(days)):
        if days[i] == days[i-1] + 1:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
                start_day = days[i-1] - current_length + 1
            current_length = 1
    if current_length > max_length:
        max_length = current_length
        start_day = days[-1] - current_length + 1
    return [max_length, start_day]
