def solve(rows):
    late_rows = [row for row in rows if row["result"] == "late"]
    grouped = {}
    for row in late_rows:
        depot = row["depot"]
        if depot not in grouped:
            grouped[depot] = {"count": 0, "total": 0}
        grouped[depot]["count"] += 1
        grouped[depot]["total"] += 1  # total rows in the group (all rows, not just late ones)

    result = []
    for depot, data in grouped.items():
        percentage = round(100 * data["count"] / data["total"], 1)
        if percentage >= 30:
            result.append((percentage, depot))

    # Sort by percentage descending, then by depot name ascending
    result.sort(key=lambda x: (-x[0], x[1]))

    # Format the result as [value, percentage] pairs
    formatted_result = []
    for percentage, depot in result:
        # Count the number of rows in the depot (all rows, not just late ones)
        total_rows = sum(1 for row in rows if row["depot"] == depot)
        formatted_result.append([total_rows, percentage])

    return formatted_result
