def solve(rows):
    # Filter rows where phase differs from 'held'
    filtered_rows = [row for row in rows if row['phase'] != 'held']

    # Group rows by site
    from collections import defaultdict
    site_groups = defaultdict(list)
    for row in filtered_rows:
        site_groups[row['site']].append(row)

    # Calculate total rows in each site group
    total_rows = {site: len(group) for site, group in site_groups.items()}

    # Calculate number of 'held' rows in each site group
    held_rows = {site: sum(1 for row in group if row['phase'] == 'held') for site, group in site_groups.items()}

    # Calculate percentage for each site
    percentages = {}
    for site, held in held_rows.items():
        total = total_rows[site]
        if total == 0:
            percentage = 0
        else:
            percentage = round(100 * held / total, 1)
        percentages[site] = percentage

    # Filter percentages >= 20
    filtered_percentages = {site: percent for site, percent in percentages.items() if percent >= 20}

    # Sort by percentage (descending), then by value (alphabetically)
    sorted_pairs = sorted(filtered_percentages.items(), key=lambda x: (-x[1], x[0]))

    # Prepare result
    result = []
    for site, percent in sorted_pairs:
        result.append((site, percent))

    # Return the list of (site, percentage) pairs
    return result
