def solve(rows):
    # Filter rows where day is 23 or less
    filtered_rows = [row for row in rows if row["day"] <= 23]

    # Group rows by driver
    driver_packages = {}
    for row in filtered_rows:
        driver = row["driver"]
        packages = row["packages"]
        if driver in driver_packages:
            driver_packages[driver].append(packages)
        else:
            driver_packages[driver] = [packages]

    # Calculate median for each driver
    median_packages = {}
    for driver, packages in driver_packages.items():
        packages.sort()
        n = len(packages)
        if n % 2 == 1:
            median = packages[n // 2]
        else:
            median = (packages[n // 2 - 1] + packages[n // 2]) / 2
        median_packages[driver] = round(median, 1)

    # Sum the rounded median packages for all drivers
    total_packages = sum(median_packages.values())
    return total_packages
```

