def solve(rows):
    filtered_rows = [row for row in rows if row['units'] >= 8]
    if not filtered_rows:
        return None
    site_totals = {}
    for row in filtered_rows:
        site = row['site']
        units = row['units']
        weight_kg = row['weight_kg']
        total = units * weight_kg
        if site in site_totals:
            site_totals[site] += total
        else:
            site_totals[site] = total
    sorted_sites = sorted(site_totals.items(), key=lambda x: (-x[1], x[0]))
    return sorted_sites[0][0]
