    balance = 0
    min_balance = float('inf')
    min_day = None

    # Process each row in ascending order (by day, then trip_id)
    for row in sorted(rows, key=lambda x: (x['day'], x['trip_id'])):
        result = row['result']

        if result == 'on_time':
            balance += row['packages']
        elif result == 'late':
            balance -= row['packages']

        # Update min balance and day if a non-ignored row is processed
        if balance != 0:
            if balance < min_balance:
                min_balance = balance
                min_day = row['day']
            elif balance == min_balance:
                # If same balance, keep the earliest day
                if row['day'] < min_day:
                    min_day = row['day']

    # Return the result based on the conditions
    if min_balance == float('inf'):
        return [0, None]
    else:
        return [min_balance, min_day]
