    drivers = {}
    for row in filtered_rows:
        driver = row['driver']
        packages = row['packages']
        if driver not in drivers:
            drivers[driver] = [packages]
        else:
            drivers[driver].append(packages)
    result = {}
    for driver, packages_list in drivers.items():
        sorted_packages = sorted(packages_list)
        n = len(sorted_packages)
        if n == 0:
            continue
        if n % 2 == 1:
            median = sorted_packages[n // 2]
        else:
            median = (sorted_packages[n // 2 - 1] + sorted_packages[n // 2]) / 2
        result[driver] = round(median, 1)
    return result
