def solve(rows):
    late_rows = [row for row in rows if row['result'] == 'late']
    if not late_rows:
        return []

    depot_counts = {}
    for row in rows:
        depot = row['depot']
        if depot not in depot_counts:
            depot_counts[depot] = {'total': 0, 'late': 0}
        depot_counts[depot]['total'] += 1

    for row in late_rows:
        depot = row['depot']
        depot_counts[depot]['late'] += 1

    result = []
    for depot, counts in depot_counts.items():
        percentage = (counts['late'] / counts['total']) * 100
        if percentage >= 30:
            result.append((round(percentage, 1), depot))

    result.sort(key=lambda x: (-x[0], x[1]))
    return result
