def solve(rows):
    filtered_rows = [row for row in rows if row['result'] != 'late']
    if not filtered_rows:
        return [0, None]

    days = sorted(set(row['day'] for row in filtered_rows))
    max_length = 0
    start_day = None

    for i in range(len(days)):
        current_length = 1
        for j in range(i + 1, len(days)):
            if days[j] == days[j - 1] + 1:
                current_length += 1
            else:
                break
        if current_length > max_length:
            max_length = current_length
            start_day = days[i]
        elif current_length == max_length:
            if days[i] < start_day:
                start_day = days[i]

    return [max_length, start_day]
