    filtered_rows = [row for row in rows if row['depot'] in {'alpha', 'delta'}]

    # Group by depot
    from collections import defaultdict
    depot_groups = defaultdict(list)
    for row in filtered_rows:
        depot_groups[row['depot']].append(row)

    # Calculate total packages per driver
    driver_packages = defaultdict(int)
    for row in filtered_rows:
        driver_packages[row['driver']] += row['packages']

    # Sort drivers by total packages (descending), then alphabetically
    sorted_drivers = sorted(driver_packages.keys(), key=lambda x: (-driver_packages[x], x))

    # Find the second highest total
    second_highest = None
    for driver in sorted_drivers:
        if len(sorted_drivers) >= 2:
            if sorted_drivers[1] != sorted_drivers[0]:
                second_highest = sorted_drivers[1]
                break
        else:
            second_highest = None

    # Return the result
    if second_highest is not None:
        return [(second_highest, second_highest)]
    else:
        return None
