def solve(rows):
    # Filter rows where depot is 'alpha' or 'delta'
    filtered_rows = [row for row in rows if row['depot'] in {'alpha', 'delta'}]

    # Group rows by depot
    depot_groups = {}
    for row in filtered_rows:
        depot = row['depot']
        if depot not in depot_groups:
            depot_groups[depot] = {'on_time': 0, 'total': 0}
        depot_groups[depot]['total'] += 1
        if row['result'] == 'on_time':
            depot_groups[depot]['on_time'] += 1

    # Calculate percentages and filter for percentages >= 35
    result = []
    for depot, group in depot_groups.items():
        on_time = group['on_time']
        total = group['total']
        if total == 0:
            percentage = 0.0
        else:
            percentage = round(100 * on_time / total, 1)
        if percentage >= 35:
            result.append((depot, percentage))

    # Sort by percentage (descending) and then by depot (ascending)
    result.sort(key=lambda x: (-x[1], x[0]))

    return result
```

